use verus::prelude::*;

/// ones_like(a) returns a vector of 1’s whose length
/// exactly matches a.len().
#[requires(true)]
#[ensures(result.len() == a.len())]
#[ensures(forall(|i: usize| i < a.len() ==> result[i] == 1))]
fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    // Pre-allocate to capacity n for efficiency
    let mut result = Vec::with_capacity(n);

    // We will push exactly n copies of 1; rewrite the for-loop as a while
    let mut i: usize = 0;
    #[invariant(i <= n)]
    #[invariant(result.len() == i)]
    #[invariant(forall(|j: usize| j < i ==> result[j] == 1))]
    #[decreases(n - i)]
    while i < n {
        result.push(1);
        i += 1;
    }

    result
}

